using System;using System.Diagnostics;namespace ServiceTool{internal static class ExecutableProbeTests{[STAThread]static int Main(){try{var self=ServiceEndpoints.InspectExecutable(Process.GetCurrentProcess().MainModule.FileName);if(self.Pid!=(uint)Process.GetCurrentProcess().Id)throw new Exception("Exact EXE process not detected");var missing=ServiceEndpoints.InspectExecutable(System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"not-running.exe"));if(missing.Pid!=0||missing.Checks.Count!=0)throw new Exception("Invented process");Console.WriteLine("PASS: standalone executable exact path and absent process; no registration or launch.");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}}}